function solve(input) {
    const seen = new Set();
    const balances = new Map();

    for (const {eventId, account, delta} of input) {
        if (seen.has(eventId)) continue;
        seen.add(eventId);

        if (!balances.has(account)) {
            balances.set(account, 0);
        }
        balances.set(account, balances.get(account) + delta);
    }

    return Array.from(balances.entries())
        .sort(([accountA], [accountB]) => accountA.localeCompare(accountB));
}
