            if (op === "delete") {
                versionMap.set(key, { version, op: "delete" });
            }
        }
    }

    const result = {};

    for (const [key, item] of versionMap) {
        if (item.op === "set") {
            result[key] = item.value;
        }
    }

    return result;
}
