function solve(input) {
    if (input.length === 0) return [];

    // Create a deep copy of input to avoid mutation
    const intervals = input.map(interval => [...interval]);

    // Sort intervals by start time
    intervals.sort((a, b) => a[0] - b[0]);

    const result = [intervals[0]];

    for (let i = 1; i < intervals.length; i++) {
        const current = intervals[i];
        const lastMerged = result[result.length - 1];

        // Check if current interval overlaps or touches the last merged interval
        if (current[0] <= lastMerged[1]) {
            // Merge intervals by extending the end of the last merged interval
            lastMerged[1] = Math.max(lastMerged[1], current[1]);
        } else {
            // No overlap, add current interval to result
            result.push(current);
        }
    }

    return result;
}
