function solve(input) {
    const cache = new Map();
    const results = [];

    for (const operation of input) {
        const { t, op, key, value, ttl } = operation;

        if (op === "put") {
            const expiration = t + ttl;
            cache.set(key, { value, expiration });
        } else if (op === "get") {
            const entry = cache.get(key);
            if (entry && entry.expiration > t) {
                results.push(entry.value);
            } else {
                results.push(null);
                if (entry) {
                    cache.delete(key);
                }
            }
        } else if (op === "delete") {
            cache.delete(key);
        }
    }

    return results;
}
